// Generates extension/src/generated/questions.js from shared/content.js, so the extension asks the
// exact questions the website asks. Run with: npm run build:extension
// test/content-sync.test.js fails if the generated file falls out of date.
import { mkdirSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { COURSE_QUESTIONS, GENERAL_QUESTIONS, LEARNING_STYLES_NOTE, NOT_OFFICIAL, PRODUCT_NAME } from '../../shared/content.js';

export function renderQuestionsModule() {
  const questions = [...COURSE_QUESTIONS, ...GENERAL_QUESTIONS].map((q) => ({
    key: q.key,
    question: q.question.replaceAll('{course}', 'this class'),
    options: q.options.map((o) => ({ value: o.value, label: o.label })),
  }));
  const data = { productName: PRODUCT_NAME, notOfficial: NOT_OFFICIAL, learningStylesNote: LEARNING_STYLES_NOTE, questions };
  return `// Generated by extension/scripts/build-content.mjs from shared/content.js. Do not edit by hand.\nexport const CONTENT = Object.freeze(${JSON.stringify(data, null, 2)});\n`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  mkdirSync(new URL('../src/generated/', import.meta.url), { recursive: true });
  const target = new URL('../src/generated/questions.js', import.meta.url);
  writeFileSync(target, renderQuestionsModule());
  console.log(`Wrote ${fileURLToPath(target)}`);
}
